import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import java.time.Instant;

/**
 * Background job worker that processes configuration update tasks
 * with full audit logging support.
 */
public class ConfigJobWorker {

    private final Map<String, Object> globalConfig;
    private final BlockingQueue<JobTask> taskQueue;
    private final AuditLogger auditLogger;
    private final Map<String, BiFunction<Map<String, Object>, String, Object>> resolvers;
    private static final Set<String> RESTRICTED_KEYS = Set.of(
            "__proto__", "__class__", "class", "constructor", "prototype",
            "classLoader", "getClass", "notify", "notifyAll", "wait");
    private static final Set<String> ALLOWED_TOP_LEVEL = Set.of(
            "app", "features", "limits", "ui", "notifications");

    public ConfigJobWorker(Map<String, Object> initialConfig) {
        this.globalConfig = new ConcurrentHashMap<>(initialConfig);
        this.taskQueue = new LinkedBlockingQueue<>();
        this.auditLogger = new AuditLogger();
        this.resolvers = initResolvers();
    }

    private Map<String, BiFunction<Map<String, Object>, String, Object>> initResolvers() {
        Map<String, BiFunction<Map<String, Object>, String, Object>> r = new HashMap<>();
        r.put("direct", (ctx, key) -> ctx.get(key));
        r.put("nested", (ctx, key) -> resolveNestedPath(ctx, key));
        r.put("computed", (ctx, key) -> computeDerivedValue(ctx, key));
        return r;
    }

    @SuppressWarnings("unchecked")
    private Object resolveNestedPath(Map<String, Object> context, String path) {
        String[] segments = path.split("\\.");
        Object current = context;
        for (String segment : segments) {
            if (current instanceof Map) {
                current = ((Map<String, Object>) current).get(segment);
            } else {
                return null;
            }
        }
        return current;
    }

    private Object computeDerivedValue(Map<String, Object> context, String expression) {
        // Simple expression: "concat:key1,key2" or "count:key"
        if (expression.startsWith("count:")) {
            Object val = context.get(expression.substring(6));
            if (val instanceof Collection) return ((Collection<?>) val).size();
            return 0;
        }
        return null;
    }

    public void submitTask(String taskId, String userId, Map<String, Object> payload) {
        JobTask task = new JobTask(taskId, userId, payload, Instant.now());
        taskQueue.offer(task);
    }

    private boolean isPathSafe(String path) {
        if (path == null || path.isEmpty()) return false;
        String[] segments = path.split("\\.");
        // First segment must be in allowed top-level keys
        if (!ALLOWED_TOP_LEVEL.contains(segments[0])) return false;
        // No segment may be a restricted key
        for (String segment : segments) {
            if (RESTRICTED_KEYS.contains(segment.toLowerCase())) return false;
            if (segment.isEmpty()) return false;
        }
        // Limit depth to prevent abuse
        if (segments.length > 5) return false;
        return true;
    }

    private boolean areKeysSafe(Map<String, Object> map) {
        for (Map.Entry<String, Object> entry : map.entrySet()) {
            String key = entry.getKey();
            if (RESTRICTED_KEYS.contains(key.toLowerCase())) return false;
            if (key.isEmpty() || key.contains(".")) return false;
            if (entry.getValue() instanceof Map) {
                @SuppressWarnings("unchecked")
                Map<String, Object> nested = (Map<String, Object>) entry.getValue();
                if (!areKeysSafe(nested)) return false;
            }
        }
        return true;
    }

    @SuppressWarnings("unchecked")
    public void processNextTask() {
        JobTask task = taskQueue.poll();
        if (task == null) return;

        auditLogger.logEvent("TASK_START", task.taskId, task.userId, null);

        try {
            Map<String, Object> payload = task.payload;
            String operation = (String) payload.getOrDefault("operation", "update");
            String targetPath = (String) payload.get("target");
            Object value = payload.get("value");
            String resolverType = (String) payload.getOrDefault("resolver", "direct");

            if (!isPathSafe(targetPath)) {
                auditLogger.logEvent("TASK_REJECTED", task.taskId, task.userId, "unsafe target path");
                return;
            }

            // Validate resolver type exists
            if (!resolvers.containsKey(resolverType)) {
                auditLogger.logEvent("TASK_REJECTED", task.taskId, task.userId, "invalid resolver");
                return;
            }

            if ("update".equals(operation)) {
                applyNestedUpdate(globalConfig, targetPath, value);
                auditLogger.logEvent("CONFIG_UPDATED", task.taskId, task.userId, targetPath);
            } else if ("merge".equals(operation)) {
                if (value instanceof Map) {
                    Map<String, Object> valueMap = (Map<String, Object>) value;
                    if (!areKeysSafe(valueMap)) {
                        auditLogger.logEvent("TASK_REJECTED", task.taskId, task.userId, "unsafe merge keys");
                        return;
                    }
                    deepMerge(globalConfig, targetPath, valueMap);
                    auditLogger.logEvent("CONFIG_MERGED", task.taskId, task.userId, targetPath);
                }
            } else if ("resolve".equals(operation)) {
                Object resolved = resolvers.get(resolverType).apply(globalConfig, targetPath);
                auditLogger.logEvent("CONFIG_RESOLVED", task.taskId, task.userId,
                        targetPath + "=" + resolved);
            } else {
                auditLogger.logEvent("TASK_REJECTED", task.taskId, task.userId, "unknown operation");
                return;
            }

            auditLogger.logEvent("TASK_COMPLETE", task.taskId, task.userId, null);
        } catch (Exception e) {
            auditLogger.logEvent("TASK_ERROR", task.taskId, task.userId, e.getMessage());
        }
    }

    @SuppressWarnings("unchecked")
    private void applyNestedUpdate(Map<String, Object> config, String path, Object value) {
        String[] segments = path.split("\\.");
        Map<String, Object> current = config;

        for (int i = 0; i < segments.length - 1; i++) {
            String segment = segments[i];
            Object next = current.get(segment);
            if (next == null || !(next instanceof Map)) {
                Map<String, Object> newMap = new ConcurrentHashMap<>();
                current.put(segment, newMap);
                next = newMap;
            }
            current = (Map<String, Object>) next;
        }

        current.put(segments[segments.length - 1], value);
    }

    @SuppressWarnings("unchecked")
    private void deepMerge(Map<String, Object> config, String basePath, Map<String, Object> incoming) {
        Map<String, Object> target = config;

        String[] baseSegments = basePath.split("\\.");
        for (String seg : baseSegments) {
            Object next = target.get(seg);
            if (next == null || !(next instanceof Map)) {
                Map<String, Object> newMap = new ConcurrentHashMap<>();
                target.put(seg, newMap);
                next = newMap;
            }
            target = (Map<String, Object>) next;
        }

        // Recursive merge - applies all keys from incoming into target
        mergeRecursive(target, incoming);
    }

    @SuppressWarnings("unchecked")
    private void mergeRecursive(Map<String, Object> target, Map<String, Object> source) {
        for (Map.Entry<String, Object> entry : source.entrySet()) {
            String key = entry.getKey();
            Object sourceVal = entry.getValue();
            Object targetVal = target.get(key);

            if (sourceVal instanceof Map && targetVal instanceof Map) {
                mergeRecursive((Map<String, Object>) targetVal, (Map<String, Object>) sourceVal);
            } else {
                target.put(key, sourceVal);
            }
        }
    }

    public Object getConfig(String path) {
        return resolveNestedPath(globalConfig, path);
    }

    public Map<String, Object> getFullConfig() {
        return Collections.unmodifiableMap(globalConfig);
    }

    // Inner classes
    static class JobTask {
        final String taskId;
        final String userId;
        final Map<String, Object> payload;
        final Instant submittedAt;

        JobTask(String taskId, String userId, Map<String, Object> payload, Instant submittedAt) {
            this.taskId = taskId;
            this.userId = userId;
            this.payload = payload;
            this.submittedAt = submittedAt;
        }
    }

    static class AuditLogger {
        private final List<AuditEntry> entries = Collections.synchronizedList(new ArrayList<>());

        void logEvent(String eventType, String taskId, String userId, String detail) {
            entries.add(new AuditEntry(Instant.now(), eventType, taskId, userId, detail));
        }

        List<AuditEntry> getEntries() {
            return Collections.unmodifiableList(entries);
        }
    }

    static class AuditEntry {
        final Instant timestamp;
        final String eventType;
        final String taskId;
        final String userId;
        final String detail;

        AuditEntry(Instant timestamp, String eventType, String taskId, String userId, String detail) {
            this.timestamp = timestamp;
            this.eventType = eventType;
            this.taskId = taskId;
            this.userId = userId;
            this.detail = detail;
        }
    }
}
